import * as T from './vendor/three.module.js';
import {makeBuilder,mergeFinish,materials} from './architecture-kit.js';
import {createRetreatAtmosphere} from './retreat-atmosphere.js';
import {conservatoryLayout} from './district-layout.js';
const TAU=Math.PI*2;
function glassHouse(root,m,rx=24,rz=21,height=22){const b=makeBuilder(root),geo=new T.SphereGeometry(1,56,24,0,TAU,0,Math.PI/2),roof=b.mesh(geo,m.glass,0,.6,0);roof.scale.set(rx,height,rz);roof.name='botanical-glass-dome';for(let i=0;i<20;i++){const a=i/20*TAU;b.tube(Array.from({length:25},(_,j)=>{const t=j/24*Math.PI/2;return[Math.sin(a)*Math.sin(t)*rx,.6+Math.cos(t)*height,Math.cos(a)*Math.sin(t)*rz];}),.055,i%5?m.silver:m.brass,root,24);}for(const t of [.45,.85,1.2,1.5]){const ring=b.ring(Math.sin(t),.003,m.silver,0,.6+Math.cos(t)*height,0);ring.scale.set(rx,rz,1);}return b;}
function plantedGarden(root,m,scale=1){const b=makeBuilder(root);for(let i=0;i<12;i++){const a=i/12*TAU,x=Math.cos(a)*12*scale,z=Math.sin(a)*10*scale;if(x>10&&Math.abs(z)<5)continue;const h=(4+i%4)*scale;b.mesh(new T.CylinderGeometry(.12,.27,h,10),m.endgrain,x,h/2,z);for(let j=0;j<9;j++){const yaw=j*TAU/9+i,length=(2+(j%3)*.4)*scale;const p=[],n=[],uv=[],idx=[];for(let k=0;k<=12;k++){const t=k/12,w=Math.sin(t*Math.PI)*.36*scale;for(const side of [-1,1]){p.push(x+Math.cos(yaw)*t*length-Math.sin(yaw)*side*w,h+.5*Math.sin(t*Math.PI)-t*t*1.1*scale,z+Math.sin(yaw)*t*length+Math.cos(yaw)*side*w);uv.push((side+1)/2,t);}if(k<12){const q=k*2;idx.push(q,q+1,q+2,q+1,q+3,q+2);}}const g=new T.BufferGeometry();g.setAttribute('position',new T.Float32BufferAttribute(p,3));g.setAttribute('uv',new T.Float32BufferAttribute(uv,2));g.setIndex(idx);g.computeVertexNormals();b.mesh(g,j%2?m.green:m.leaf);}}}
export function buildConservatoryLandmark(parent){const root=new T.Group();root.name='aurora-conservatory-landmark';root.position.set(conservatoryLayout.x,0,0);parent.add(root);const m=materials(),b=glassHouse(root,m,23,20,22);b.mesh(new T.CylinderGeometry(1,1,.25,80),m.darkStone,0,.03,0).scale.set(23.3,1,20.3);plantedGarden(root,m,.8);for(const side of [-1,1]){b.box(.35,5,.4,m.cream,23,2.5,side*2.6);b.box(.06,4.6,.09,m.coolLamp,23.22,2.5,side*2.6);}b.tube(Array.from({length:25},(_,i)=>{const a=i/24*Math.PI;return[23,5+Math.sin(a)*2.6,Math.cos(a)*2.6];}),.16,m.brass);mergeFinish(root);return{root,update(){},setQuality(){}};}
export function buildConservatoryInterior(root,m){
 const b=glassHouse(root,m,30,27,24);b.mesh(new T.CylinderGeometry(1,1,.2,80),m.darkStone,0,-.02,0).scale.set(30,1,27);const floor=b.mesh(new T.CircleGeometry(1,80),m.cream,0,.09,0);floor.scale.set(29.6,26.6,1);floor.rotation.x=-Math.PI/2;
 b.mesh(new T.CylinderGeometry(1,1,.12,64),m.darkStone,0,.08,0).scale.set(9,1,7.5);const pool=b.mesh(new T.CircleGeometry(1,64),m.water,0,.18,0);pool.rotation.x=-Math.PI/2;pool.scale.set(8.5,7,1);plantedGarden(root,m,1);
 for(let i=0;i<44;i++){const a=i/44*TAU;b.oval(i%2?m.stone:m.darkStone,Math.cos(a)*8.8,.25,Math.sin(a)*7.3,.45,.25,.4);}
 // Two gradual side ramps lead to an elevated north gallery; no hidden teleport.
 const deckShape=new T.Shape();deckShape.moveTo(-20,16);deckShape.lineTo(20,16);deckShape.lineTo(13,22);deckShape.lineTo(-13,22);deckShape.closePath();const deck=b.mesh(new T.ExtrudeGeometry(deckShape,{depth:.18,bevelEnabled:false}),m.cedar,0,2.91,0);deck.rotation.x=-Math.PI/2;for(const x of [-19,19]){const ramp=b.box(4,.16,Math.hypot(19,3),m.cedar,x,1.5,-6.5);ramp.rotation.x=Math.atan2(3,19);for(const side of [-1,1])for(let i=0;i<=10;i++){const z=3-i*1.9,y=(3-z)/19*3;b.rod([x+side*1.8,y+.1,z],[x+side*1.8,y+1.15,z],.045,m.silver);b.rod([x+side*1.8,y+1.15,z],[x+side*1.8,y+1.45,z-1.9],.035,m.brass);}}for(const z of [-16.3,-21.8]){const half=z< -20?12.8:18;for(let x=-half;x<=half;x+=1.8)b.rod([x,3.1,z],[x,4.2,z],.04,m.silver);b.rod([-half,4.2,z],[half,4.2,z],.05,m.brass);b.rod([-half,3.4,z],[half,3.4,z],.02,m.coolLamp);}for(const side of [-1,1])b.rod([side*19.8,4.2,-16.1],[side*13,4.2,-21.8],.05,m.brass);
 for(let i=0;i<13;i++)b.oval(i%2?m.stone:m.darkStone,(i%4-1.5)*1.1,1+i*.45,-7.2,.8,.7,.6);const time={value:0};const falls=new T.ShaderMaterial({transparent:true,depthWrite:false,side:T.DoubleSide,uniforms:{time},vertexShader:'varying vec2 vUv;void main(){vUv=uv;gl_Position=projectionMatrix*modelViewMatrix*vec4(position,1.);}',fragmentShader:'varying vec2 vUv;uniform float time;void main(){float a=sin(vUv.x*76.+sin(vUv.y*12.+time*2.))*sin(vUv.y*30.+time*4.);float edge=smoothstep(0.,.1,vUv.x)*(1.-smoothstep(.9,1.,vUv.x));gl_FragColor=vec4(.62,.85,.88,edge*(.32+.15*a));}'});b.mesh(new T.PlaneGeometry(3.4,6.2,12,16),falls,0,3.5,-6.7);
 const atmosphere=createRetreatAtmosphere(root,{name:'botanical',waters:[{x:0,y:.19,z:0,rx:8.4,rz:6.8}],vapour:[{x:0,y:.3,z:-6.4,rx:2,rz:.8,rise:1.7,size:.6,count:30,opacity:.12}],fireflies:[{x:0,y:6,z:0,rx:17,rz:15,rise:7,count:48,color:'#b6e6d4'}],ribbons:[],lamps:[{x:0,y:.14,z:18,rx:4,rz:3}]});
 const fill=new T.HemisphereLight('#c9e9e4','#254438',1.2);root.add(fill);mergeFinish(root);return{root,walls:[],doors:[],uniforms:[{time}],atmosphere,update(){},setQuality(){}};
}
